import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    people = []
    index = 1
    for _ in range(n):
        ai = int(input[index])
        bi = int(input[index + 1])
        people.append((ai, bi))
        index += 2

    current_floor = 1
    time = 0
    queue = []

    for ai, bi in people:
        while queue and (queue[0][0] != current_floor or len(queue) == 4):
            if queue[0][0] == current_floor:
                time += 1  # Letting people out
                queue.pop(0)
            else:
                if queue[0][0] > current_floor:
                    current_floor += 1
                else:
                    current_floor -= 1
                time += 1

        if ai == current_floor:
            time += 1  # Getting in
            queue.append((bi, bi))
        else:
            queue.append((ai, bi))
            if ai > current_floor:
                while current_floor < ai:
                    current_floor += 1
                    time += 1
            else:
                while current_floor > ai:
                    current_floor -= 1
                    time += 1
            time += 1  # Getting in

    while queue:
        if queue[0][0] == current_floor:
            time += 1  # Letting people out
            queue.pop(0)
        else:
            if queue[0][0] > current_floor:
                current_floor += 1
            else:
                current_floor -= 1
            time += 1

    print(time)

if __name__ == "__main__":
    main()
